<template>
  <div style="overflow: visible" class="tab-content" v-show="title === selectedTitle">
    <slot />
  </div>
</template>

<script>
import { inject } from "vue";

export default {
  name: "VehicleTab",
  props: ["title"],
  setup() {
    const selectedTitle = inject("selectedTitle");

    return {
      selectedTitle,
    };
  },
};
</script>

<style scoped lang="scss">
.tab-content {
  min-width: 100%;
}
</style>
