<template>
  <div class="lobbies">
    <div
      v-for="lobby in devMode ? devLobbies : lobbies"
      :key="lobby.id"
      :class="['lobby']"
      :style="{
        background: 'linear-gradient(rgba(31, 31, 31, 0.7),rgba(31, 31, 31, 0.9)),  url(' + lobby.background + ') no-repeat center center',
        backgroundSize: 'cover',
      }"
    >
      <div class="info">
        <div class="lobby-name">
          {{ lobby.name }}
          <div class="lobby-locked"><i v-show="lobby.password" class="bx bx-lock-alt"></i></div>
        </div>
        <div class="lobby-info">
          <div v-show="lobby.gamemode" class="lobby-gamemode">{{ lobby.gamemode }}</div>
          <div v-show="lobby.description" class="lobby-description">{{ lobby.description }}</div>
          <div class="players players-alt">
            <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span
            ><i class="fas fa-users"></i>
          </div>
        </div>
      </div>
      <div class="players players-main">
        <span class="lobby-stats">{{ lobby.players }}/{{ lobby.maxplayers }}</span
        ><i class="fas fa-users"></i>
      </div>
      <div class="join">
        <button
          :class="['join-button', { current: currentLobby === lobby.id, full: lobby.players === lobby.maxplayers && currentLobby !== lobby.id }]"
          @click="joinParty(lobby.id, lobby.name, lobby.players, lobby.maxplayers, lobby.password)"
          :disabled="lobby.players === lobby.maxplayers || currentLobby === lobby.id"
        >
          <div v-if="currentLobby === lobby.id">Joined</div>
          <div v-else-if="lobby.maxplayers === 0">N/A</div>
          <div v-else-if="lobby.players === lobby.maxplayers">Full</div>
          <div v-else>Join</div>
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "LobbiesTab",
  props: ["devMode"],
  methods: {
    joinParty(id, name, players, maxplayers, password) {
      if (!password) {
        // eslint-disable-next-line no-undef
        mp.trigger("PutPlayerInLobby", id, "");
        return;
      }
      // eslint-disable-next-line no-undef
      mp.trigger("MenuToggleTyping", true);
      // eslint-disable-next-line no-undef
      Swal.fire({
        title: "Lobby Password",
        input: "password",
        inputAttributes: {
          autocapitalize: "off",
        },
        showCancelButton: true,
        confirmButtonText: "Join",
        buttonsStyling: false,
        customClass: {
          confirmButton: "lobby-pass-confirm",
          cancelButton: "lobby-pass-cancel",
          input: "lobby-pass-input",
        },
      }).then((result) => {
        // eslint-disable-next-line no-undef
        mp.trigger("MenuToggleTyping", false);
        if (result.isConfirmed) {
          // eslint-disable-next-line no-undef
          mp.trigger("PutPlayerInLobby", id, result.value);
        }
      });
    },
  },
  data() {
    return {
      currentLobby: null,
      lobbies: [],
      devLobbies: [
        {
          id: 0,
          name: "Copchase 1",
          background: "https://live.staticflickr.com/7526/16232917915_3ef3d4ab4d_b.jpg",
          gamemode: "Copchase",
          password: "sex",
          players: 11,
          maxplayers: 25,
        },
        {
          id: 1,
          name: "Copchase 2",
          description: "Optional description",
          background: "https://wallpapercave.com/wp/wp4501529.jpg",
          gamemode: "Copchase",
          players: 14,
          maxplayers: 35,
        },
        {
          id: 2,
          name: "Copchase 3",
          background: "https://wallpapers-hub.art/wallpaper-images/192181.jpg",
          gamemode: "Copchase",
          players: 8,
          maxplayers: 20,
        },
        {
          id: 3,
          name: "Copchase 4",
          background: "https://c4.wallpaperflare.com/wallpaper/519/763/782/gta-5-background-desktop-wallpaper-preview.jpg",
          gamemode: "Copchase",
          players: 15,
          maxplayers: 15,
        },
      ],
    };
  },
};

/*
[{
        id: 0,
        name: 'Copchase 1',
        background: 'https://live.staticflickr.com/7526/16232917915_3ef3d4ab4d_b.jpg',
        gamemode: 'Copchase',
        password: 'sex',
        players: 11,
        maxplayers: 25
      }, {
        id: 1,
        name: 'Copchase 2',
        description: 'Optional description',
        background: 'https://wallpapercave.com/wp/wp4501529.jpg',
        gamemode: 'Copchase',
        players: 14,
        maxplayers: 35
      }, {
        id: 2,
        name: 'Copchase 3',
        background: 'https://wallpapers-hub.art/wallpaper-images/192181.jpg',
        gamemode: 'Copchase',
        players: 8,
        maxplayers: 20
      }, {
        id: 3,
        name: 'Copchase 4',
        background: 'https://c4.wallpaperflare.com/wallpaper/519/763/782/gta-5-background-desktop-wallpaper-preview.jpg',
        gamemode: 'Copchase',
        players: 15,
        maxplayers: 15
      }]
 */
</script>

<style lang="scss">
.lobby-pass-confirm {
  background: none !important;
  border: 2px solid $blue !important;
  color: $white-text !important;
  padding: 10px 30px !important;
  font-size: 15px !important;
  cursor: pointer !important;
  transition: background 0.4s;
  margin-right: 10px;
  font-weight: bold !important;
  border-radius: 15px !important;

  &:hover {
    background: $blue !important;
  }

  &:focus {
    border: 2px solid $blue !important;
    outline: none !important;
    background: $blue !important;
  }
}

.lobby-pass-cancel {
  background: none !important;
  border: 2px solid lighten($foreground, 10%) !important;
  color: lighten($foreground, 10%) !important;
  padding: 10px 30px !important;
  font-size: 15px !important;
  cursor: pointer !important;
  transition: background 0.4s;
  margin-right: 10px;
  font-weight: bold !important;
  border-radius: 15px !important;

  &:hover {
    background: lighten($foreground, 10%) !important;
    color: $white-text !important;
  }

  &:focus {
    border: 2px solid lighten($foreground, 10%) !important;
    outline: none !important;
    background: lighten($foreground, 10%) !important;
    color: $white-text !important;
  }
}
</style>

<style scoped lang="scss">
.lobby-description {
  @media only screen and (max-width: 1000px) {
    display: none;
  }
}

.lobby-locked {
  color: lighten($foreground, 20%);
  font-size: 25px;
  margin-top: 4px;
}

/* width */
::-webkit-scrollbar {
  width: 0px;
}

.lobbies {
  display: grid;
  grid-template-columns: auto auto;
  grid-gap: 10px;
  overflow-y: auto !important;
  max-height: 720px;
}

.lobby {
  display: flex;
  border: 2px solid $foreground;
  height: 130px;
  border-radius: 15px;

  .info {
    flex: 0.6;
    padding: 10px 0px 0px 30px;
    color: $white-text;
    font-weight: 300;
  }

  .lobby-name {
    color: $white-text;
    font-size: 25px;
    font-weight: 300;
    display: flex;
  }

  .players-main {
    flex: 0.3;
    display: flex;
    justify-content: center;
    align-items: center;
    @media only screen and (max-width: 1000px) {
      display: none;
    }
  }

  .players-alt {
    display: none;

    @media only screen and (max-width: 1000px) {
      display: block;
    }
  }

  .players {
    font-size: 20px;
    color: $white-text;

    .lobby-stats {
      margin-right: 7px;
      font-weight: 300;
    }

    .fas {
      color: lighten($foreground, 20%);
      font-size: 25px;
    }
  }

  .join {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 0.4;
  }

  .join-button {
    background: none;
    border: 2px solid $blue;
    color: $white-text;
    padding: 10px 30px;
    font-size: 20px;
    cursor: pointer;
    transition: background 0.4s;
    border-radius: 15px;

    &:hover {
      background: $blue;
    }
  }

  .current {
    background: #2d6ae3;
    border: 2px solid #2d6ae3;

    &:hover {
      background: #2d6ae3;
    }
  }

  .full {
    border: 2px solid $sago-gray2;
    color: $sago-gray2;
    cursor: default;

    &:hover {
      background: none;
    }
  }
}
</style>
